arguments.command:
cd /workspace && find submission -name "__pycache__" -prune -exec rm -rf {} \; ; find submission -name "*.pyc" -delete; find submission | sort && python3 -c "
import os
tot=0;entries=0
for base,dirs,files in os.walk('/workspace/submission'):
    for name in dirs+files:
        entries+=1
        p=os.path.join(base,name)
        if os.path.isfile(p): tot+=os.path.getsize(p)
print('entries',entries,'bytes',tot)
" && python3 public_check.py submission
